import{_ as n,a0 as s,w as i,s as o,I as r,x as e,a1 as l,A as p,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"以太網分離器會降低網速嗎？ | LCTT x X-CMD","titleTemplate":false,"description":"以太網分離器會降低網速嗎？ | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"以太網分離器會降低網速嗎？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"以太網分離器會降低網速嗎？ | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20220716 Does an Ethernet splitter slow down speed-","title":"以太網分離器會降低網速嗎？","tag":"202208","desc":""},"relativePath":"202208/20220716 Does an Ethernet splitter slow down speed-.md","filePath":"[post].md"}'),u={name:"202208/20220716 Does an Ethernet splitter slow down speed-.md"};function m(b,t,h,f,w,g){const a=s("Link");return i(),o("div",null,[t[24]||(t[24]=r("h1",{id:"以太網分離器會降低網速嗎",tabindex:"-1"},[e("以太網分離器會降低網速嗎？ "),r("a",{class:"header-anchor",href:"#以太網分離器會降低網速嗎","aria-label":"Permalink to “以太網分離器會降低網速嗎？”"},"​")],-1)),t[25]||(t[25]=r("p",null,[r("img",{src:"https://img.linux.net.cn/data/attachment/album/202208/10/104845ishhhse3meqzuamd.jpg",alt:""})],-1)),t[26]||(t[26]=r("blockquote",null,[r("p",null,"這篇文章詳細總結了以太網分離器，以及它們的速度，還有各種常見問題等信息，來幫助你選擇最合適的硬件。")],-1)),r("p",null,[t[1]||(t[1]=r("ruby",null,[e("交換機"),r("rt",null,"Switch")],-1)),t[2]||(t[2]=e("、",-1)),t[3]||(t[3]=r("ruby",null,[e("集線器"),r("rt",null,"Hub")],-1)),t[4]||(t[4]=e("，還有",-1)),t[5]||(t[5]=r("ruby",null,[e("以太網分離器"),r("rt",null,"Ethernet Splitter")],-1)),t[6]||(t[6]=e(" 是用來幫助擴展網絡的網絡設備。這其中，最基礎的設備就是小巧的以太網分離器了。它們是一種小型設備，可以將一個以太網信號分成兩個。它們簡單易用，並且還便宜。這可以算是最簡單的網絡設備之一了，因為它們不需要提供電源，也沒有特定的按鍵或者 LED 燈來提示狀態。只是在一個小設備上有三個以太網端口，其中兩個在一側，另一個在另一側。有些品種是在一側有帶着一小段 ",-1)),l(a,{href:"https://en.wikipedia.org/wiki/Registered_jack"},{default:p(()=>[...t[0]||(t[0]=[e("RJ45",-1)])]),_:1}),t[7]||(t[7]=e(" 接口的網線，另一側是兩個以太網端口。",-1))]),t[27]||(t[27]=d('<p>儘管在網絡世界中，分離器已經存在了相當長一段時間了，很多人還是不知道如何有效使用它們。與普遍的看法相反的是，以太網分離器應該總是成對購買。直接把分離器的一端和路由器連接，再把兩個設備與分離器的兩個端口連接，這樣是不行的。想讓分離器在網絡中正常工作，是有一個正確的設置技巧的。</p><h3 id="如何使用以太網分離器進行一個基本的設置" tabindex="-1">如何使用以太網分離器進行一個基本的設置 <a class="header-anchor" href="#如何使用以太網分離器進行一個基本的設置" aria-label="Permalink to “如何使用以太網分離器進行一個基本的設置”">​</a></h3><p>要讓不同房間的兩個設備連接到主信號源，以太網分離器是非常方便的。大多數情況下，它們可以節約網線、牆上的網絡插座，並提供了可靠的連接。就像之前説的，以太網分離器是成對出售的。一個分離器將來自設備（通常是路由器）上的信號合併，然後另一個把信號分成兩個信道，這樣就可以讓兩個設備通信了。</p><p>路由器在房間 A，兩個 PC 在房間 B，但是每個房間的牆上只有一個以太網插座。這種情況下，就需要一個分離器，兩條網線連到路由器上，網線的另外一端連到分離器上，然後分離器的另一端連到房間 A 牆上的接口。這樣路由器的兩個信號就合併到一起了。接下來，另一個分離器只有一個端口的那一端接到房間 B 牆上的接口上。從房間 A 合併的信號現在就會分成兩個，這樣在房間 B 裏面，你就可以有兩個以太網端口了。</p><p>分離器的優勢是它可以大量減少牆上的接口，也會大量減少你這種情況下所需的網線。它會幫你避免“網線地獄”，因為這樣會將所需要的端口/網線降低兩倍。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/10/sample-diagram-using-ethernet-splitter-1024x896.jpg" alt="sample diagram using ethernet splitter"></p><h3 id="以太網分離器會降低網速嗎-1" tabindex="-1">以太網分離器會降低網速嗎？ <a class="header-anchor" href="#以太網分離器會降低網速嗎-1" aria-label="Permalink to “以太網分離器會降低網速嗎？”">​</a></h3><p>網絡連接會變慢嗎？這可能是你想到的常見問題之一。好吧，答案取決於你的網絡類型。理想情況下，分離器是 BASE-T 標準，也就是<ruby>快速以太網<rt>Fast Ethernet</rt></ruby>。它們可以支持高達 Mbps 級的速度。</p><p>如果分離器在一個 100Mbps 的網絡中使用，答案是否定的，它是不會降低網速的。然而，如果你的路由器可以提供 1Gbps 傳輸速率，然後你在中間用了一個分離器，那麼帶寬將被限制在 100Mbps。這種情況下，分離器確實會限制速度，連接會變慢。</p><h3 id="以太網分離器的優勢和劣勢" tabindex="-1">以太網分離器的優勢和劣勢 <a class="header-anchor" href="#以太網分離器的優勢和劣勢" aria-label="Permalink to “以太網分離器的優勢和劣勢”">​</a></h3><p>以太網分離器在一些情況下很有用，但是它們也有一些缺點。首先，每個以太網端口只能提供最高 100Mbps 的速度。因為這個限制，網絡中能夠提供高於 100Mbps 的資源就不能被合理優化了。另外，因為你能連接的設備數量被限制在兩個，如果你有兩個以上的設備，以太網分離器並不是最佳選擇。</p><p>此外，如果路由器只剩下一個以太網端口，使用分離器是不現實的；這時候就只能做一些犧牲了。然後，儘管它們可以減少把兩個網絡合並所需要的網線，這種方式需要兩個分離器才能工作。</p><p>另一方面，以太網分離器也有一些優勢。它們比起傳統的網絡設備要便宜，也不需要複雜的設置。不像其他網絡設備，它們也不需要軟件和其他配置。在設備不多的家庭網絡中，比如説一個房間最多兩個設備，以太網分離器是一個很好的選擇。如果你只需要 100Mbps 的網絡，只有兩個設備要連接，以太網分離器是最好的選項。</p><p>以太網分離器出現已經很長時間了，但是由於非常簡單，也沒有太多可以改進的空間。它們仍然是基於過時的 <ruby>快速以太網<rt>Fast Ethernet</rt></ruby> 標準，這也許和今天高速網絡的需求有點格格不入。儘管有它們的優勢，大多數情況下，它們還真不是一個現實的解決方案。隨着現在技術的進步，以太網分離器的前景依然光明。也許某個天才可以讓它用在 <ruby>千兆以太網<rt>Gigabit Ethernet</rt></ruby> 標準上。</p><p>現在你已經對以太網分離器有一些瞭解了，下面是一些常見問題（FAQ）。</p><h3 id="常見問題" tabindex="-1">常見問題 <a class="header-anchor" href="#常見問題" aria-label="Permalink to “常見問題”">​</a></h3><h4 id="可以把一條以太網線分到兩個設備上嗎" tabindex="-1">可以把一條以太網線分到兩個設備上嗎？ <a class="header-anchor" href="#可以把一條以太網線分到兩個設備上嗎" aria-label="Permalink to “可以把一條以太網線分到兩個設備上嗎？”">​</a></h4><p>如果你想把一條以太網線分到兩個設備上，這是很正常的想法。然而，這就需要買一個以太網線共享分離套件。分離器套件可以讓多個設備同時使用同一條網線。如果你想把 PC 和筆記本，或者 PC 和遊戲主機，同時連到同一個網線上，這是個不錯的選擇。</p><p>説到連接速度，以太網線會超過其他連接方式。當有些東西需要快速連接，比如説遊戲，以太網線通常都是最好的選擇。</p><p>需要指出的是，你不能用一個網線連接兩個設備，因為它們只是為一個設備而設計的，這也就是為什麼你需要一個以太網分離器。它會連到一個已有的網線上，然後為兩個設備提供連接。</p><h4 id="我怎麼把兩個設備連到一個以太網端口" tabindex="-1">我怎麼把兩個設備連到一個以太網端口？ <a class="header-anchor" href="#我怎麼把兩個設備連到一個以太網端口" aria-label="Permalink to “我怎麼把兩個設備連到一個以太網端口？”">​</a></h4><p>兩個設備可以連到一個以太網端口。然而，就像之前説的，你需要使用網線共享套件。這是因為每個以太網連接是為一個單個設備設計的。</p><p>有了以太網線共享套件，你就可以給一個以太網端口連上多個設備了，這對於家庭網絡來説是非常方便的。如果你有不多的幾個以太網連接可用，然後需要很多的 LAN 連接，這肯定有用。</p><p>還需要説的一點是，如果你有多餘的以太網端口可用，如果是這種情況，最好的選擇是給每個設備分配一個端口。當這種情況不行的時候，網線共享套件或者分離器是一個完美的備選方案。</p><h4 id="以太網分離器和交換機有什麼區別" tabindex="-1">以太網分離器和交換機有什麼區別？ <a class="header-anchor" href="#以太網分離器和交換機有什麼區別" aria-label="Permalink to “以太網分離器和交換機有什麼區別？”">​</a></h4><p>以太網分離器和交換機工作起來差不多，但是從根本上是不同的。以太網分離器可以在同一根以太網線上運行兩個獨立的連接。然而，這最多就是兩個連接。如果你只想要一個另外的設備連到這個以太網上，這是個不錯的選擇。但是，再有其他設備就不行了。</p><p>如果你想往一個以太網連接上連很多個設備，就需要買一個以太網交換機。除了可以允許多於兩個設備連接外，交換機和以太網分離器相似。如果有很多要連接的設備，但是隻有幾個以太網端口，交換機是非常方便的，比如説你正在連接很多設備到 LAN。</p><p>雖然它們支持堆疊，但需要記住的是，它們也需要供電。交換機和分離器的另一個不同是，分離器不要供電，可以直接連到以太網端口。</p><h4 id="我需要以太網交換機還是分離器" tabindex="-1">我需要以太網交換機還是分離器？ <a class="header-anchor" href="#我需要以太網交換機還是分離器" aria-label="Permalink to “我需要以太網交換機還是分離器？”">​</a></h4><p>你要連接的設備的數量決定了是需要一個交換機還是分離器。如果只需要連兩個設備，可以用以太網分離器，也不用給他供電。</p><p>相反的，如果需要連幾個設備，以太網交換機是一個理想的解決方案。它可以連接幾個設備到同一個以太網端口，但是它需要供電。</p><p>我希望這篇指南能幫你瞭解以太網分離器以及如果使用它們。從網上可以以很低的價格買到。然而，如果需要超過 100Mbps 的速度，也許你需要給你的網絡配置一下線路。</p>',32)),r("p",null,[l(a,{href:"https://www.debugpoint.com/category/hardware"},{default:p(()=>[...t[8]||(t[8]=[e("這篇文章是我們硬件指南的一部分。",-1)])]),_:1})]),t[28]||(t[28]=r("p",null,[r("em",null,"Featured Photo by Jainath Ponnala on Unsplash")],-1)),t[29]||(t[29]=r("hr",null,null,-1)),r("p",null,[t[10]||(t[10]=e("via: ",-1)),l(a,{href:"https://www.debugpoint.com/ethernet-splitter-speed/"},{default:p(()=>[...t[9]||(t[9]=[e("https://www.debugpoint.com/ethernet-splitter-speed/",-1)])]),_:1})]),r("p",null,[t[15]||(t[15]=e("作者：",-1)),l(a,{href:"https://www.debugpoint.com/author/admin1/"},{default:p(()=>[...t[11]||(t[11]=[e("Arindam",-1)])]),_:1}),t[16]||(t[16]=e(" 選題：",-1)),l(a,{href:"https://github.com/lkxed"},{default:p(()=>[...t[12]||(t[12]=[e("lkxed",-1)])]),_:1}),t[17]||(t[17]=e(" 譯者：",-1)),l(a,{href:"https://github.com/Yufei-Yan"},{default:p(()=>[...t[13]||(t[13]=[e("MCGA",-1)])]),_:1}),t[18]||(t[18]=e(" 校對：",-1)),l(a,{href:"https://github.com/%E6%A0%A1%E5%B0%8D%E8%80%85ID"},{default:p(()=>[...t[14]||(t[14]=[e("校對者ID",-1)])]),_:1})]),r("p",null,[t[21]||(t[21]=e("本文由 ",-1)),l(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[19]||(t[19]=[e("LCTT",-1)])]),_:1}),t[22]||(t[22]=e(" 原創編譯，",-1)),l(a,{href:"https://linux.cn/"},{default:p(()=>[...t[20]||(t[20]=[e("Linux中國",-1)])]),_:1}),t[23]||(t[23]=e(" 榮譽推出",-1))])])}const k=n(u,[["render",m]]);export{C as __pageData,k as default};
